<?php require 'includes/header.php';$q=db()->prepare('SELECT p.*,c.name cname FROM products p LEFT JOIN collections c ON c.id=p.collection_id WHERE p.slug=? AND p.visible=1');$q->execute([$_GET['slug']??'']);$p=$q->fetch();if(!$p){http_response_code(404);echo '<section class="section"><h2>Ürün bulunamadı</h2></section>';require 'includes/footer.php';exit;}?><section class="section"><div class="cards2"><div><img style="width:100%" src="<?=e($p['image']?:'images/hero/hero-placeholder.svg')?>"></div><div><div class="gold"><?=e($p['code'])?></div><h2><?=e($p['name'])?></h2><p class="muted"><?=nl2br(e($p['description']))?></p><p><b>Ölçü:</b> <?=e($p['size'])?></p><p><b>Stok:</b> <?=e(stock_label($p['stock']))?></p><p><b>Fiyat:</b> <?=e($p['price']?:'Teklif Al')?></p><a class="btn" href="https://wa.me/<?=e(setting('whatsapp'))?>?text=<?=urlencode('Merhaba, '.$p['code'].' kodlu '.$p['name'].' ürünü için toptan fiyat almak istiyorum.')?>">WhatsApp Teklif</a></div></div></section><?php require 'includes/footer.php';?>
